class SparseArray
  include Enumerable

  def initialize
    @store = {}
  end

  # Store a value at the given index.
  def []=(index, value)
    @store[index] = value
  end

  # Retrieve the value at the given index (returns nil if never set).
  def [](index)
    @store[index]
  end

  # Iterate over the stored values in ascending index order.
  # If a block is given, yields each value; otherwise returns an Enumerator.
  def each(&block)
    if block_given?
      @store.keys.sort.each { |i| yield @store[i] }
      self
    else
      enum_for(:each)
    end
  end
end
