# Registry implementation
class Registry
  def initialize
    @items = []          # preserves insertion order
  end

  # Registers +obj+ if it is not already present (by identity).
  # Returns self to allow chaining.
  def register(obj)
    @items << obj unless @items.any? { |i| i.equal?(obj) }
    self
  end

  # Returns true only if +obj+ (the exact same object) has been registered.
  def registered?(obj)
    @items.any? { |i| i.equal?(obj) }
  end

  # Number of distinct registered objects.
  def size
    @items.size
  end

  # Returns a copy of the registered objects in registration order.
  def to_a
    @items.dup
  end
end
