class OpenRecord
  def initialize(**attrs)
    @attributes = {}
    attrs.each do |key, value|
      @attributes[key] = value
      # create getter and setter for each initial attribute
      define_singleton_method(key) { @attributes[key] }
      define_singleton_method("#{key}=") { |v| @attributes[key] = v }
    end
  end

  private

  def respond_to_missing?(sym, include_all = false)
    if sym.to_s.end_with?('=')
      attr = sym.to_s[0..-2].to_sym
      @attributes.key?(attr)          # setter exists iff the attribute has been set
    elsif @attributes.key?(sym)
      true                            # getter exists iff the attribute has been set
    else
      super
    end
  end

  def method_missing(sym, *args, &block)
    if sym.to_s.end_with?('=')               # writer: age=
      attr = sym.to_s[0..-2].to_sym
      @attributes[attr] = args.first
      # define getter and setter for fast future access
      define_singleton_method(attr) { @attributes[attr] }
      define_singleton_method("#{attr}=") { |v| @attributes[attr] = v }
      @attributes[attr]
    else                                      # reader: age
      if @attributes.key?(sym)
        @attributes[sym]
      else
        super                                 # raise NoMethodError as usual
      end
    end
  end
end
```

**Explanation**

* **Storage** – `@attributes` holds the actual values keyed by symbol.
* **Initialization** – For each keyword given, we store the value and immediately define a singleton getter and setter so that `respond_to?` reports them as available right away.
* **Writer (`method_missing` for `foo=`)** – We store the value, then define both the getter (`foo`) and setter (`foo=`) on the object's singleton class. Subsequent calls go straight to those defined methods, making the attribute readable instantly.
* **Reader (`method_missing` for `foo`)** – If the attribute exists we return its value; otherwise we delegate to `super`, which raises `NoMethodError` just like any undefined method.
* **`respond_to_missing?`** – Allows `respond_to?` to work correctly:
  * A getter (`:foo`) is recognized only when `:foo` is present in `@attributes`.
  * A setter (`:=`) is recognized only when the corresponding attribute has been set (i.e., the getter would succeed).
  * For any other symbol we fall back to the default behavior.

