class OpenRecord
  # Create a new record with the given keyword arguments.
  def initialize(**attrs)
    @attributes = {}
    attrs.each { |k, v| @attributes[k] = v }
  end

  # Handle dynamic getters and setters.
  def method_missing(mid, *args)
    if mid.to_s.end_with?('=')                     # writer:  foo=
      attr = mid.to_s.chomp('=').to_sym
      @attributes[attr] = args.first               # return the assigned value
    else                                           # reader:  foo
      if @attributes.key?(mid)
        @attributes[mid]
      else
        super                                      # raise NoMethodError
      end
    end
  end

  # Tell #respond_to? which missing methods we can handle.
  def respond_to_missing?(mid, include_private = false)
    if mid.to_s.end_with?('=')                     # any writer is always allowed
      true
    else                                             # a reader works only if the attribute exists
      @attributes.key?(mid)
    end
  end
end
```

This implementation:

* Stores attributes in a hash (`@attributes`).
* Returns the attribute value for a getter if the attribute exists; otherwise it delegates to `super`, raising `NoMethodError`.
* Accepts any writer method (`foo=`), creates/updates the attribute, and returns the assigned value.
* Makes `respond_to?` report `true` for a getter only when the attribute has been set (via constructor or a prior writer), and always `true` for a writer, matching the required behaviour.

